from datatrove.pipeline.filters.base_filter import BaseFilter
from datatrove.pipeline.writers import JsonlWriter

class Mixed(BaseFilter):
    name = "mixed"
    def filter(self, doc):
        if doc.text.startswith("r"):
            return False, "starts_with_r"
        return not doc.text.startswith("x")

out = path("removed")
block = Mixed(exclusion_writer=JsonlWriter(out, compression=None))
kept = ids(block, [D("red", id="1"), D("xray", id="2"), D("blue", id="3")])
result = [kept, tree(out)]

from datatrove.pipeline.readers import JsonlReader
folder = put(path("data"), {"a.jsonl": jsonl({"content": "alpha", "key": "k1", "n": 1}, {"content": "beta", "key": "k2"})})
def adapter(self, data, path, id_in_file):
    return {"text": data["content"].upper(), "id": "%s-%s" % (data["key"], id_in_file), "metadata": {"tk": self.text_key}}
result = [run(JsonlReader(folder, text_key="content", id_key="key", add_file_path=False)),
          run(JsonlReader(folder, text_key="content", adapter=adapter, add_file_path=False))]
